void Solver::bump_var(int var, double coeff) {
    // Fast path: update activity
    activity[var] += var_inc * coeff;

    // Rescale if activity exceeds safe limit
    static const double LIMIT = 1e100;
    static const double SCALE = 1e-100;
    if (activity[var] > LIMIT) {
        // Scale all variable activities in a tight loop
        double *ptr = &activity[1];
        for (int i = vars; i > 0; --i) {
            *ptr++ *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
